// Hand-written. Not generated by Speakeasy.
//
// The version lives in .speakeasy/gen.yaml and the generator copies it into
// internal/sdk/authlete.go, examples/provider/provider.tf and, from that
// example, docs/index.md. Those three are generated and must agree with it.
//
// A plain `speakeasy run` increments the version by itself, so between
// releases those files name a version nobody can install. That is harmless
// only because the registry renders the tagged commit: the release procedure
// is `speakeasy run --set-version <the tag>` immediately before tagging, so
// the commit that ships names exactly the version that ships. Nothing is
// edited by hand, which is why the version line stays in the example rather
// than being removed. Removing it conflicts on every run, because the
// generator writes it back.
//
// The README is the exception. It is maintained by hand and frozen against
// regeneration, so a version in it cannot track anything and goes stale; the
// repo has already carried 0.0.8, 0.0.16, 0.0.18 and a stranded 0.0.17 at
// once. Its installation snippet points at the registry page instead.
package provider

import (
	"os"
	"regexp"
	"strings"
	"testing"
)

// declaredVersion reads the version the generator works from.
func declaredVersion(t *testing.T) string {
	t.Helper()
	b, err := os.ReadFile("../../.speakeasy/gen.yaml")
	if err != nil {
		t.Fatalf("cannot read gen.yaml: %v", err)
	}
	m := regexp.MustCompile(`(?m)^  version: (\S+)$`).FindSubmatch(b)
	if m == nil {
		t.Fatal("no terraform version in .speakeasy/gen.yaml")
	}
	v := strings.TrimSpace(string(m[1]))
	if v == "" {
		t.Fatal("gen.yaml declares an empty version")
	}
	return v
}

// TestREADMEPinsNoVersion keeps a version out of the one file that cannot
// track one.
func TestREADMEPinsNoVersion(t *testing.T) {
	b, err := os.ReadFile("../../README.md")
	if err != nil {
		t.Fatalf("cannot read README.md: %v", err)
	}
	re := regexp.MustCompile(`(?m)^\s*version\s*=\s*"([^"]+)"`)
	for _, m := range re.FindAllStringSubmatch(string(b), -1) {
		t.Errorf("README.md pins version %s.\n\n"+
			"The installation block is frozen against regeneration, so this "+
			"number is maintained by hand and will go stale. Drop it and let "+
			"the registry page carry the current release.", m[1])
	}
}

// TestGeneratedVersionsAgree catches a regeneration applied to some files and
// reverted in others, which is how docs/index.md once held a stale 0.0.18.
func TestGeneratedVersionsAgree(t *testing.T) {
	want := declaredVersion(t)

	generated := map[string]*regexp.Regexp{
		"../sdk/authlete.go":                  regexp.MustCompile(`SDKVersion:\s*"([^"]+)"`),
		"../../examples/provider/provider.tf": regexp.MustCompile(`(?m)^\s*version\s*=\s*"([^"]+)"`),
		"../../docs/index.md":                 regexp.MustCompile(`(?m)^\s*version\s*=\s*"([^"]+)"`),
	}
	for path, re := range generated {
		b, err := os.ReadFile(path)
		if err != nil {
			t.Fatalf("cannot read %s: %v", path, err)
		}
		found := re.FindAllStringSubmatch(string(b), -1)
		if len(found) == 0 {
			t.Errorf("%s reports no version. It is generated and should carry %s.", path, want)
			continue
		}
		for _, m := range found {
			if m[1] != want {
				t.Errorf("%s reports version %s while gen.yaml says %s.\n\n"+
					"Both are generated, so disagreeing means a regeneration was "+
					"partly reverted. Regenerate, or revert the rest.", path, m[1], want)
			}
		}
	}
}

// TestModulePathMatchesMajor guards Go's semantic import versioning rule. A
// major of 2 or more needs a matching /vN suffix on the module path, and the
// generator rewrites its own imports to use it. Getting this wrong fails the
// build inside the generator rather than here, with an error that reads as a
// missing package.
func TestModulePathMatchesMajor(t *testing.T) {
	want := declaredVersion(t)
	major := strings.SplitN(want, ".", 2)[0]

	b, err := os.ReadFile("../../go.mod")
	if err != nil {
		t.Fatalf("cannot read go.mod: %v", err)
	}
	m := regexp.MustCompile(`(?m)^module (\S+)$`).FindSubmatch(b)
	if m == nil {
		t.Fatal("no module line in go.mod")
	}
	path := string(m[1])

	if major == "0" || major == "1" {
		if regexp.MustCompile(`/v\d+$`).MatchString(path) {
			t.Errorf("go.mod module path is %s but the version is %s. "+
				"Only a major of 2 or more takes a /vN suffix.", path, want)
		}
		return
	}
	if suffix := "/v" + major; !strings.HasSuffix(path, suffix) {
		t.Errorf("go.mod module path is %s but the version is %s, so it has "+
			"to end in %s.\n\nGo requires the suffix for a major of 2 or "+
			"more. Without it the generated code imports the published "+
			"module instead of this one and the build fails inside the "+
			"generator.", path, want, suffix)
	}
}
